1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Per-country rule for the national-number length an E.164 telephone must carry after its
7	 * country calling code: '+61' (Australia) requires 9 national digits, '+1' (NANP) requires
8	 * 10. A number whose country code is not listed here has no per-country constraint beyond
9	 * {@link TelephoneNormalizer}'s generic 8-15 digit bound. Kept separate from
10	 * {@link TelephoneNormalizer} so canonicalization (used to compare against stored owners)
11	 * stays lenient while the create request is held to the stricter, country-specific length.
12	 */
13	final class E164CountryLength {
14	
15	    /** Country calling code -> required national-number length. Matched longest-code-first,
16	     *  so a code that is a prefix of another still resolves to the more specific rule. */
17	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of(
18	            "61", 9,
19	            "1", 10);
20	
21	    private E164CountryLength() {
22	    }
23	
24	    /**
25	     * Returns {@code true} when {@code e164} (a '+' followed by digits, as produced by
26	     * {@link TelephoneNormalizer#toE164}) carries the national-number length required for its
27	     * country code, or when its country code has no configured length. A {@code null} or
28	     * non-E.164 argument returns {@code false}.
29	     */
30	    static boolean isNationalLengthValid(String e164) {
31	        if (e164 == null || !e164.startsWith("+")) {
32	            return false;
33	        }
34	        String digits = e164.substring(1);
35	        String code = longestMatchingCode(digits);
36	        if (code == null) {
37	            return true;
38	        }
39	        return digits.length() - code.length() == NATIONAL_DIGITS.get(code);
40	    }
41	
42	    /** The longest configured country code that prefixes {@code digits}, or {@code null}. */
43	    private static String longestMatchingCode(String digits) {
44	        String best = null;
45	        for (String code : NATIONAL_DIGITS.keySet()) {
46	            if (digits.startsWith(code) && (best == null || code.length() > best.length())) {
47	                best = code;
48	            }
49	        }
50	        return best;
51	    }
52	}
