19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
26	    @Mapping(target = "initials", expression = "java(initials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
33	    @Mapping(target = "sharesHousehold", ignore = true)
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /** Format an owner's name as 'LastName, FirstName' for display. */
37	    default String displayName(Owner owner) {
38	        return owner.getLastName() + ", " + owner.getFirstName();
39	    }
40	
41	    /** Upper-cased first letters of first and last name, dot-separated with a trailing dot (e.g. 'J.S.'). */
42	    default String initials(Owner owner) {
43	        return initial(owner.getFirstName()) + initial(owner.getLastName());
44	    }
45	
46	    private static String initial(String name) {
47	        return Character.toUpperCase(name.charAt(0)) + ".";
48	    }
49	
50	    /**
51	     * Derive the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last
52	     * two digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). Returns null when
53	     * either source field is absent.
54	     */
55	    default String membershipNumber(Owner owner) {
56	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
57	            return null;
58	        }
59	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
60	    }
61	
62	    /**
63	     * Derive the Luhn check digit (0 to 9) over the digits of the owner's customer code.
64	     * Returns null when the customer code has not yet been assigned.
65	     */
66	    default Integer checkDigit(Owner owner) {
67	        if (owner.getCustomerCode() == null) {
68	            return null;
69	        }
70	        return Luhn.checkDigit(owner.getCustomerCode());
71	    }
72	
73	    /**
74	     * Derive the owner's locality (canonical region) as the region component of the customer
75	     * code identity, or 'UNKNOWN' when the code carries no region.
76	     */
77	    default String locality(Owner owner) {
78	        return CustomerCode.regionOf(owner.getCustomerCode());
79	    }
80	
81	    /** Derive the owner's numeric membership level (1 to 3). */
82	    default Integer membershipLevel(Owner owner) {
83	        return MembershipLevels.of(owner);
84	    }
85	
86	    /** Derive the owner's preferred contact method: EMAIL when an email is present, otherwise PHONE. */
87	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
88	        return owner.hasEmail() ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
89	    }
90	
91	    /**
92	     * Derive the owner's age band from the birth date as at the registration date, or null
93	     * when no birth date was supplied.
94	     */
95	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
96	        AgeBand band = AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate());
97	        return band == null ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
98	    }
99	
100	    Owner toOwner(OwnerDto ownerDto);
101	
102	    @Mapping(target = "id", ignore = true)
103	    @Mapping(target = "pets", ignore = true)
104	    Owner toOwner(OwnerFieldsDto ownerDto);
105	
106	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
107	
108	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
109	
110	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
111	        OwnerPageDto ownerPageDto = new OwnerPageDto();
112	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
113	        ownerPageDto.setPage(ownerPage.getNumber());
114	        ownerPageDto.setSize(ownerPage.getSize());
115	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
116	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
117	        return ownerPageDto;
118	    }
119	}
