3	import net.officefloor.plugin.section.clazz.Parameter;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	public class InvalidTelephoneExceptionHandler {
10	
11	    public void handle(@Parameter InvalidTelephoneException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
14	                "The telephone must be a valid E.164 number (a '+' followed by 8 to 15 digits) "
15	                        + "with the national-number length its country code requires "
16	                        + "('+61' needs 9 national digits, '+1' needs 10)");
17	        detail.setProperty("rejectedValue", ex.getRejectedValue());
18	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
19	    }
20	}
